mutations.old:
seen = set()
for e in ledger.read_all():
    if e.get("kind") != "candidate_snapshot":
        continue
    cid = ((e.get("payload") or {}).get("candidate") or {}).get("candidate_id")
    if cid:
        seen.add(cid)
return sorted(seen)

mutations.new:
seen = []
for e in ledger.read_all():
    if e.get("kind") != "candidate_snapshot":
        continue
    cid = ((e.get("payload") or {}).get("candidate") or {}).get("candidate_id")
    if cid and cid not in seen:
        seen.append(cid)
return seen
